const tabId = 103795220;
// Check if Mamma Maria or Contessa or Mare have direct reservation pages on OpenTable
const testUrls = [
  "https://www.opentable.com/r/mare-boston",
  "https://www.opentable.com/r/mamma-maria-boston",
  "https://www.opentable.com/r/contessa-boston",
  "https://www.opentable.com/r/bricco-boston"
];

const checkResults = [];
for (const url of testUrls) {
  await tool.navigate({ tabId, url });
  await tool.wait_for({ tabId, condition: "load_state", value: "load", timeout_ms: 6000 });
  const data = await browserjs(tabId, () => {
    return {
      title: document.title,
      h1: document.querySelector("h1")?.textContent?.trim(),
      url: window.location.href,
      notFound: document.body.innerText.includes("Well, this is embarrassing") || document.body.innerText.includes("Page not found")
    };
  });
  checkResults.push({ url, data });
}

console.log("Check results:", JSON.stringify(checkResults, null, 2));

